final class AppDelegate: UIResponder, UIApplicationDelegate {
  // Process level, once per launch: DI graph, analytics, push registration
  func application(_ app: UIApplication,
                   didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
    Services.bootstrap()
    return true
  }

  // Which scene configuration to use when the system connects a new window
  func application(_ app: UIApplication,
                   configurationForConnecting session: UISceneSession,
                   options: UIScene.ConnectionOptions) -> UISceneConfiguration {
    UISceneConfiguration(name: "Default", sessionRole: session.role)
  }
}

final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  var window: UIWindow?

  func scene(_ scene: UIScene, willConnectTo session: UISceneSession,
             options: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene else { return }
    window = UIWindow(windowScene: windowScene)   // one window per scene — never a singleton
    window?.rootViewController = RootViewController()
    window?.makeKeyAndVisible()
    if let url = options.urlContexts.first?.url { route(to: url) }
  }

  func sceneDidBecomeActive(_ scene: UIScene) { resumeTimers() }
  func sceneWillResignActive(_ scene: UIScene) { pauseTimers() }

  func sceneDidEnterBackground(_ scene: UIScene) {
    saveDraft()                                   // you get seconds here, not minutes
    let id = UIApplication.shared.beginBackgroundTask { }
    Task {
      await flushAnalytics()
      UIApplication.shared.endBackgroundTask(id)
    }
  }
}

final class GradientButton: UIButton {
  // Back the view with the layer type you need instead of syncing frames in layoutSubviews
  override class var layerClass: AnyClass { CAGradientLayer.self }
  private var gradient: CAGradientLayer { layer as! CAGradientLayer }

  override init(frame: CGRect) {
    super.init(frame: frame)
    gradient.colors = [UIColor.systemBlue.cgColor, UIColor.systemIndigo.cgColor]
    gradient.startPoint = .zero
    gradient.endPoint = CGPoint(x: 1, y: 1)
    layer.cornerRadius = 12
    layer.cornerCurve = .continuous
  }
  required init?(coder: NSCoder) { fatalError("use init(frame:)") }
}

