protocol EditorDelegate: AnyObject {   // class-bound, so the property can be weak
  func editor(_ editor: EditorViewController, didSave draft: Draft)
  func editorDidCancel(_ editor: EditorViewController)
}

final class EditorViewController: UIViewController {
  weak var delegate: EditorDelegate?   // strong here would close the retain cycle

  private func save() {
    delegate?.editor(self, didSave: draft)   // sender first, by convention
  }
}

final class InboxViewController: UIViewController, EditorDelegate {
  func showEditor() {
    let editor = EditorViewController()
    editor.delegate = self       // I own the editor; it only points back weakly
    present(editor, animated: true)
  }

  func editor(_ editor: EditorViewController, didSave draft: Draft) {
    store.insert(draft)
    editor.dismiss(animated: true)
  }
}

// Optional methods without @objc: a default implementation in an extension
extension EditorDelegate {
  func editorDidCancel(_ editor: EditorViewController) { editor.dismiss(animated: true) }
}

