struct SearchBar: UIViewRepresentable {
  @Binding var text: String

  func makeUIView(context: Context) -> UISearchBar {
    let bar = UISearchBar()
    bar.delegate = context.coordinator     // the delegate lives on the coordinator
    return bar
  }

  func updateUIView(_ bar: UISearchBar, context: Context) {
    if bar.text != text { bar.text = text }   // guard, or you fight the user's cursor
  }

  func makeCoordinator() -> Coordinator { Coordinator(text: $text) }

  final class Coordinator: NSObject, UISearchBarDelegate {
    private let text: Binding<String>
    init(text: Binding<String>) { self.text = text }

    func searchBar(_ bar: UISearchBar, textDidChange value: String) {
      text.wrappedValue = value   // UIKit -> SwiftUI flows back through the binding
    }
  }
}

